generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(xsd:decimal(?shortfallSum)) AS ?categoryShortfall)
       (SUM(xsd:decimal(?holdingValueSum)) AS ?categoryHoldingValue)
       (AVG(xsd:decimal(?allocationAvg)) AS ?categoryAvgAllocationPct)
       (AVG(xsd:decimal(?liquidityAvg)) AS ?categoryAvgLiquidityScore)
       (AVG(xsd:decimal(?diversificationAvg)) AS ?categoryAvgDiversificationScore)
WHERE {
  {
    SELECT ?investorId ?category (SUM(xsd:decimal(?holdingValue)) AS ?holdingValueSum)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:currentValue ?holdingValue ;
          wm:hasCategory ?cat .
      ?cat rdfs:label ?category .
    }
    GROUP BY ?investorId ?category
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?shortfallSum)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:investorId ?investorId ;
          wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?allocationPct)) AS ?allocationAvg)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?liquidityScore)) AS ?liquidityAvg)
           (AVG(xsd:decimal(?diversificationScore)) AS ?diversificationAvg)
    WHERE {
      ?phl a wm:PortfolioHealth ;
           wm:investorId ?investorId ;
           wm:liquidityScore ?liquidityScore ;
           wm:diversificationScore ?diversificationScore .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?category

